function arrayStats(arr) {
  var sum = arr.reduce(function(a, b) { return a + b; }, 0);
  return {
    sum: sum,
    mean: sum / arr.length,
    min: Math.min.apply(null, arr),
    max: Math.max.apply(null, arr)
  };
}

function filterAndAverage(employees, minAge) {
  var filtered = employees.filter(function(e) { return e.age >= minAge; });
  if (filtered.length === 0) return 0;
  var total = filtered.reduce(function(sum, e) { return sum + e.salary; }, 0);
  return total / filtered.length;
}

function cleanData(data) {
  var valid = data.filter(function(x) { return x !== null && x !== undefined; });
  if (valid.length === 0) return data.map(function() { return 0; });
  var mean = Math.round((valid.reduce(function(a, b) { return a + b; }, 0) / valid.length) * 100) / 100;
  return data.map(function(x) { return (x === null || x === undefined) ? mean : x; });
}

function groupByAvg(data, groupKey, valueKey) {
  var groups = {};
  data.forEach(function(row) {
    var key = row[groupKey];
    if (!groups[key]) groups[key] = [];
    groups[key].push(row[valueKey]);
  });
  var result = {};
  Object.keys(groups).forEach(function(key) {
    var vals = groups[key];
    result[key] = vals.reduce(function(a, b) { return a + b; }, 0) / vals.length;
  });
  return result;
}

function minMaxNormalize(arr) {
  var min = Math.min.apply(null, arr);
  var max = Math.max.apply(null, arr);
  if (max === min) return arr.map(function() { return 0; });
  return arr.map(function(x) { return (x - min) / (max - min); });
}
